import { Component, OnInit } from '@angular/core';
import { SafeUrl } from '@angular/platform-browser';
import { G } from '../../../../core/common/G';
import { SiteLanguageService } from '../../../../core/i18n/site-language.service';

@Component({
  selector: 'app-footer',
  templateUrl: './footer.component.html',
  styleUrls: ['./footer.component.scss']
})
export class FooterComponent implements OnInit {

  currentDate = new Date().getFullYear();
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  androidApp = 'http://localhost:4300/assets/file/AvalAmooz.apk';

  isPhone = false;
  readonly androidAppEnabled = G.AndroidAppEnabled;
  width = 1200;

  constructor(public language: SiteLanguageService) {

  }

  isMainHost(): boolean {

    return window.location.hostname === 'avalamooz.ir' ? true : false;
  }

  showZPTrust() {

    // window.open(
    //   'https://www.zarinpal.com/trustPage/' + window.location.hostname,
    //   null,
    //   'width=450, height=600, scrollbars=no, resizable=no'
    // );

    window.open(
      'https://www.zarinpal.com/trustPage/' + 'avalamooz.ir',
      null,
      'width=450, height=600, scrollbars=no, resizable=no'
    );
  }

  ngOnInit(): void {

    G.getWindowWidth().subscribe(
      res => {

        this.width = res;
      }
    );

    this.isPhone = G.IsAndroid;

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    this.androidApp = G.AndroidApp;
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }
}
